import pandas as pd

def fill_defaults(stock):
    """Fill missing qty with 0 and missing price with 9.99."""
    return stock.fillna({"qty": 0, "price": 9.99})

import pandas as pd

def serious_respondents(survey, min_answers):
    """Return names of respondents with at least min_answers answers."""
    answered = survey[["q1", "q2", "q3", "q4"]].notna().sum(axis=1)
    return survey.loc[answered >= min_answers, "respondent"].reset_index(drop=True)

import pandas as pd

def ledger_total(ledger):
    """Return the total of parseable amounts, rounded to 2 decimals."""
    text = ledger["amount"].astype(str).str.strip().str.replace(",", "")
    amounts = pd.to_numeric(text, errors="coerce")
    return round(float(amounts.sum()), 2)
